def link(label,path):
    if not path:return f'[{label}](https://github.com/laadkke-arch/agentflow-open/tree/{DATA_SHA}/docs/workstreams/research/AF-RES-070)'
    return f'[{label}]({path})' if path in ('Q_CHECK.csv','REPRODUCE.md','REVIEW.md') else f'[{label}]({BASE}{path})'
def rowid(i):return f'[{i}]({ci[i]["original_url"]}) / '+link('A·B 원행','CASES.json')
def evid(i):
    es=[];seen=set()
    for p in pins:
        if p['issue_id']==i and (p['source_id'],p['section']) not in seen:
            seen.add((p['source_id'],p['section']));es.append(f'[{p["source_id"]} {p["section"]}]({p["pinned_url"]})')
    return '; '.join(es)
def cell(s):return str(s).replace('|','\\|').replace('\n',' / ').replace('\r','')
def table(headers,rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(cell(x) for x in row)+' |' for row in rows])

